package com.nexuszero.mt.core;import java.util.*;public final class EvidenceVault{private final List<String>items=new ArrayList<>();public void add(String level,String kind,String value,String source){items.add("["+level+"] "+kind+": "+value+" @ "+source);}public String report(){StringBuilder o=new StringBuilder("NEXUS EVIDENCE VAULT\n");for(String e:items)o.append(e).append('\n');return o.toString();}}